export function testOnceDoesNotSkipTheNextHandler() {
  const bus = new EventBus();
  const calls: string[] = [];
  bus.once('ready', () => calls.push('once'));
  bus.on('ready', () => calls.push('always'));
  assertEqual(bus.emit('ready'), 2); // fails: 1
}

export function testOnAnySeesEveryEvent() {
  const bus = new EventBus();
  const seen: string[] = [];
  bus.onAny((event) => seen.push(event));
  bus.emit('save');
  bus.emit('load');
  assertEqual(seen, ['save', 'load']);
}
